      const choices=node("div","knowledge-actions knowledge-graph-levels");for(const [level,title] of [["overview","Process overview"],["steps","Process steps"],["all","All entities"]]){const b=button(title,()=>{graphLevel=level;render();},"knowledge-tab");b.setAttribute("aria-pressed",String(graphLevel===level));choices.append(b);}root.append(choices);
      const display=graphLevel==="overview"?data.entities.filter(e=>e.type==="process_version"):graphLevel==="steps"?data.entities.filter(e=>["process_version","step","decision"].includes(e.type)):data.entities;
